char	*get_next_line(int fd)
{
	static char	*stash;
	char		*line;
	char		*buf;

	if (fd < 0 || BUFFER_SIZE <= 0)
		return (NULL);
	buf = malloc(BUFFER_SIZE + 1);
	if (!buf)
		return (NULL);
	stash = read_and_stash(fd, stash, buf);
	free(buf);
	if (!stash)
		return (NULL);
	line = extract_line(stash);
	stash = update_stash(stash);
	return (line);
}

int	ft_printf(const char *format, ...)
{
	va_list	args;
	int		count = 0;

	va_start(args, format);
	while (*format)
	{
		if (*format == '%')
			count += handle_format(*(++format), args);
		else
			count += write(1, format, 1);
		format++;
	}
	va_end(args);
	return (count);
}

int	handle_format(char spec, va_list args)
{
	if (spec == 'c')
		return (ft_putchar_len(va_arg(args, int)));
	if (spec == 's')
		return (ft_putstr_len(va_arg(args, char *)));
	if (spec == 'p')
		return (ft_putptr_len(va_arg(args, void *)));
	if (spec == 'd' || spec == 'i')
		return (ft_putnbr_len(va_arg(args, int)));
	if (spec == 'u')
		return (ft_putunbr_len(va_arg(args, unsigned int)));
	return (0);
}

char	*read_and_stash(int fd, char *stash, char *buf)
{
	int	bytes_read = 1;

	while (!ft_strchr(stash, '\n') && bytes_read != 0)
	{
		bytes_read = read(fd, buf, BUFFER_SIZE);
		if (bytes_read == -1)
			return (NULL);
		buf[bytes_read] = '\0';
		stash = ft_strjoin_gnl(stash, buf);
	}
	return (stash);
}

char	*extract_line(char *stash)
{
	int	i = 0;

	if (!stash[i])
		return (NULL);
	while (stash[i] && stash[i] != '\n')
		i++;
	char *line = malloc(i + 2);
	if (!line)
		return (NULL);
	i = 0;
	while (stash[i] && stash[i] != '\n')
	{
		line[i] = stash[i];
		i++;
	}
	if (stash[i] == '\n')
		line[i++] = '\n';
	line[i] = '\0';
	return (line);
}

char	*update_stash(char *stash)
{
	int	i = 0;

	while (stash[i] && stash[i] != '\n')
		i++;
	if (!stash[i])
	{
		free(stash);
		return (NULL);
	}
	char *new_stash = malloc(strlen(stash) - i + 1);
	if (!new_stash)
		return (NULL);
	i++;
	int j = 0;
	while (stash[i])
		new_stash[j++] = stash[i++];
	new_stash[j] = '\0';
	free(stash);
	return (new_stash);
}

int	ft_putnbr_base(long n, char *base)
{
	int	count = 0;
	int	base_len = strlen(base);

	if (n < 0)
	{
		count += write(1, "-", 1);
		n = -n;
	}
	if (n >= base_len)
		count += ft_putnbr_base(n / base_len, base);
	count += write(1, &base[n % base_len], 1);
	return (count);
}

int	ft_putptr_len(void *ptr)
{
	unsigned long	addr = (unsigned long)ptr;
	int				count = write(1, "0x", 2);

	count += ft_puthex_len(addr, "0123456789abcdef");
	return (count);
}

void	ft_striteri(char *s, void (*f)(unsigned int, char *))
{
	if (!s || !f)
		return ;
	for (unsigned int i = 0; s[i]; i++)
		f(i, &s[i]);
}

char	*ft_strmapi(char const *s, char (*f)(unsigned int, char))
{
	if (!s || !f)
		return (NULL);
	char *res = malloc(strlen(s) + 1);
	if (!res)
		return (NULL);
	for (unsigned int i = 0; s[i]; i++)
		res[i] = f(i, s[i]);
	res[strlen(s)] = '\0';
	return (res);
}
